css:
/* Hallmark v2.0.0 · shape: Ledger Index · genre: modern-minimal · theme: custom (ledger editorial, headless) · job: sign up · hero: split, ruled sheet and swiped card · nav: wordmark, two links, one action · footer: close-band foot · imagery: CSS ledger and card, no photographs · signature: the half-swiped card behind a categorised ledger sheet · copy: verbatim */
/* critique: The ruled sheet risks reading as decoration; the half-swiped card and duplicate bracket tie it to the headline, and the page relies on type scale rather than invented proof. */
/* waive: theme deal skipped — the skill scripts are outside the run sandbox; palette and type derived by hand. */
/* waive: tokens.css and base.css are merged into this file — the brief requires one self-contained HTML document. */
/* answered: no photographs, logos, quotes or numbers were supplied; the product image is built in CSS with no claims in it. */

:root {
  --paper: #f2ede2;
  --paper-raised: #faf6ec;
  --ink: #191713;
  --ink-soft: #4f4a40;
  --ink-faint: #6b6355;
  --rule: #d5cdbd;
  --rule-strong: #a89f8d;
  --signal: #ad3a17;
  --signal-bright: #e06a45;
  --dark: #191713;
  --dark-soft: #b9b1a1;
  --dark-rule: #3c372e;
  --band-rule: #c16745;
  --card-chip: #d9cba9;
  --shadow: #d8cfbd;
  --shadow-strong: #c9bfab;
  --focus: #1f5cff;
  --focus-on-dark: #faf6ec;
  --clear: transparent;
  --font-display: ui-serif, "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --font-body: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --container: 1280px;
  --gutter: clamp(20px, 4.5vw, 56px);
  --col-gap: clamp(28px, 4vw, 56px);
  --radius-card: 6px;
  --radius-chip: 2px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  overflow-x: clip;
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  overflow-x: clip;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection {
  background: var(--signal);
  color: var(--paper-raised);
}

.container {
  width: calc(100% - (2 * var(--gutter)));
  max-width: var(--container);
  margin-inline: auto;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: clip;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

a {
  color: inherit;
}

a:focus-visible,
button:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
}

.site-header {
  border-bottom: 1px solid var(--rule);
}

.header-inner {
  display: flex;
  align-items: center;
  gap: 28px;
  min-height: 76px;
}

.wordmark {
  flex: none;
  color: var(--ink);
  font-family: var(--font-display);
  font-size: clamp(1.375rem, 2vw, 1.5rem);
  font-weight: 600;
  letter-spacing: -0.025em;
  line-height: 1;
  text-decoration: none;
}

a.wordmark {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
}

.primary-nav {
  display: flex;
  align-items: center;
  gap: 28px;
  margin-left: auto;
}

.primary-nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--ink-soft);
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1;
  text-decoration: none;
  transition: color 160ms ease;
}

.primary-nav a:hover {
  color: var(--ink);
}

.header-cta {
  margin-left: 4px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 24px;
  border: 1px solid var(--ink);
  border-radius: 0;
  background: var(--ink);
  color: var(--paper-raised);
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.1;
  text-align: center;
  cursor: pointer;
  transition: background-color 160ms ease, border-color 160ms ease, color 160ms ease, transform 160ms ease;
}

.btn:hover {
  background: var(--signal);
  border-color: var(--signal);
  color: var(--paper-raised);
}

.btn:active {
  transform: translateY(1px);
}

.btn-small {
  min-height: 44px;
  padding-inline: 16px;
  font-size: 0.9375rem;
}

.btn-quiet {
  display: inline-flex;
  align-items: center;
  min-height: 48px;
  padding: 0 0 5px;
  border-bottom: 1px solid var(--rule-strong);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.1;
  text-decoration: none;
  transition: color 160ms ease, border-color 160ms ease;
}

.btn-quiet:hover {
  color: var(--signal);
  border-color: var(--signal);
}

.hero {
  padding-block: clamp(44px, 7vw, 88px) clamp(56px, 8vw, 104px);
}

.hero-inner {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: clamp(24px, 3vw, 40px);
  align-items: center;
}

.hero-copy {
  grid-column: 1 / span 8;
  min-width: 0;
}

.hero h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.55rem, 6.8vw, 6rem);
  font-weight: 500;
  letter-spacing: -0.045em;
  line-height: 0.96;
  overflow-wrap: break-word;
  min-width: 0;
}

.hero-sub {
  max-width: 46ch;
  margin: clamp(24px, 3vw, 32px) 0 0;
  color: var(--ink-soft);
  font-size: 1.125rem;
  line-height: 1.55;
  overflow-wrap: break-word;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 16px 28px;
  margin-top: clamp(28px, 3vw, 40px);
}

.hero-art {
  position: relative;
  grid-column: 9 / span 4;
  justify-self: end;
  width: 100%;
  max-width: 430px;
  min-width: 0;
  padding: 12px 14px 56px 0;
}

.sheet {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: clamp(14px, 2vw, 22px);
  width: 100%;
  aspect-ratio: 0.82;
  padding: clamp(20px, 2.4vw, 28px) clamp(18px, 2.4vw, 26px) clamp(20px, 2.4vw, 28px) clamp(38px, 4.5vw, 52px);
  border: 1px solid var(--rule-strong);
  background: var(--paper-raised);
  box-shadow: 14px 14px 0 var(--shadow);
  transform: rotate(-2.5deg);
}

.sheet::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 clamp(24px, 3vw, 34px);
  width: 1px;
  background: var(--signal);
  opacity: 0.42;
}

.sheet-head,
.sheet-foot {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sheet-mark {
  flex: none;
  width: 9px;
  height: 9px;
  background: var(--signal);
}

.sheet-check {
  flex: none;
  width: 12px;
  height: 12px;
  color: var(--signal);
}

.sheet-line,
.sheet-foot-line {
  height: 1px;
  flex: 1;
  background: var(--rule);
}

.sheet-foot-line {
  background: var(--rule-strong);
}

.sheet-foot-mark {
  flex: none;
  width: 22px;
  height: 4px;
  background: var(--ink);
}

.ledger {
  display: flex;
  flex-direction: column;
}

.ledger-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-block: clamp(6px, 1.2vw, 11px);
  border-bottom: 1px solid var(--rule);
}

.ledger-row:last-child {
  border-bottom: 0;
}

.ledger-bar {
  width: var(--w, 50%);
  height: 6px;
  background: var(--ink);
  opacity: 0.76;
}

.ledger-tag {
  flex: none;
  width: 9px;
  height: 9px;
  background: var(--rule-strong);
}

.ledger-tag.is-signal {
  background: var(--signal);
}

.ledger-tag.is-faint {
  background: var(--rule);
}

.ledger-pair {
  margin-left: calc(-1 * clamp(10px, 1.4vw, 14px));
  padding-left: clamp(8px, 1.2vw, 12px);
  border-left: 2px solid var(--signal);
}

.ledger-pair .ledger-bar {
  background: var(--signal);
  opacity: 0.9;
}

.ledger-pair .ledger-tag {
  background: var(--signal);
}

.ledger-pair + .ledger-row {
  border-top: 1px solid var(--rule);
}

.bank-card {
  position: absolute;
  bottom: 6px;
  left: 0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 57%;
  aspect-ratio: 1.6;
  padding: 7% 7% 6%;
  border: 1px solid var(--ink);
  border-radius: var(--radius-card);
  background: var(--ink);
  box-shadow: 8px 10px 0 var(--shadow-strong);
  transform: rotate(6deg);
  animation: card-swipe 520ms cubic-bezier(0.22, 0.61, 0.36, 1) both;
}

@keyframes card-swipe {
  from {
    transform: rotate(6deg) translateX(26px);
    opacity: 0.55;
  }
  to {
    transform: rotate(6deg) translateX(0);
    opacity: 1;
  }
}

.card-chip {
  width: 19%;
  aspect-ratio: 1.35;
  border-radius: var(--radius-chip);
  background: var(--card-chip);
}

.card-wave {
  position: absolute;
  top: 8%;
  right: 8%;
  width: 15%;
  height: auto;
  color: var(--paper-raised);
  opacity: 0.85;
}

.card-brand {
  color: var(--paper-raised);
  font-family: var(--font-display);
  font-size: 0.875rem;
  font-weight: 500;
  letter-spacing: 0.01em;
  line-height: 1;
}

.features {
  padding-bottom: clamp(8px, 2vw, 24px);
}

.features .container {
  border-top: 1px solid var(--rule-strong);
}

.feature {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  gap: var(--col-gap);
  padding-block: clamp(30px, 4vw, 48px);
  border-bottom: 1px solid var(--rule);
}

.feature-head {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  min-width: 0;
}

.feature-icon {
  flex: none;
  width: 28px;
  height: 28px;
  margin-top: 3px;
  color: var(--ink);
}

.feature h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 2.2vw, 2rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.05;
  overflow-wrap: break-word;
  min-width: 0;
}

.feature p {
  max-width: 54ch;
  margin: 0;
  color: var(--ink-soft);
  font-size: 1.125rem;
  line-height: 1.6;
}

.how {
  margin-top: clamp(24px, 5vw, 56px);
  padding-block: clamp(56px, 7vw, 88px);
  background: var(--dark);
  color: var(--paper-raised);
}

.steps {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--col-gap);
  margin: 0;
  padding: 0;
  list-style: none;
}

.step {
  min-width: 0;
  padding-top: 20px;
  border-top: 1px solid var(--dark-rule);
}

.step-n {
  display: block;
  color: var(--signal-bright);
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 400;
  font-variant-numeric: lining-nums tabular-nums;
  letter-spacing: -0.04em;
  line-height: 1;
}

.step h3 {
  margin: clamp(16px, 2vw, 22px) 0 10px;
  color: var(--paper-raised);
  font-family: var(--font-display);
  font-size: clamp(1.5rem, 2.2vw, 2rem);
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.1;
  overflow-wrap: break-word;
  min-width: 0;
}

.step p {
  max-width: 34ch;
  margin: 0;
  color: var(--dark-soft);
  font-size: 1rem;
  line-height: 1.6;
}

.how a:focus-visible,
.how button:focus-visible {
  outline-color: var(--focus-on-dark);
}

.close-band {
  position: relative;
  overflow: clip;
  padding-top: clamp(64px, 9vw, 120px);
  background: var(--signal);
  color: var(--paper-raised);
}

.close-band::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: repeating-linear-gradient(to bottom, var(--clear) 0 63px, var(--band-rule) 63px 64px);
  opacity: 0.38;
  pointer-events: none;
}

.close-band .container {
  position: relative;
  z-index: 1;
}

.close-inner {
  display: grid;
  grid-template-columns: minmax(0, 8fr) minmax(0, 4fr);
  gap: var(--col-gap);
  align-items: end;
  padding-bottom: clamp(56px, 7vw, 96px);
}

.close-band h2 {
  max-width: 18ch;
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(2.6rem, 6.5vw, 5.5rem);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.98;
  overflow-wrap: break-word;
  min-width: 0;
}

.close-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 18px;
  padding-bottom: 8px;
}

.close-actions .btn:hover {
  border-color: var(--paper-raised);
  background: var(--paper-raised);
  color: var(--ink);
}

.btn-link-paper {
  min-height: 48px;
  border-bottom-color: var(--paper-raised);
  color: var(--paper-raised);
}

.btn-link-paper:hover {
  border-bottom-color: var(--paper);
  color: var(--paper);
}

.close-band a:focus-visible,
.close-band button:focus-visible {
  outline-color: var(--focus-on-dark);
}

.close-foot {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 24px;
  padding-block: 20px;
  border-top: 1px solid var(--band-rule);
  color: var(--paper-raised);
}

.close-foot .wordmark {
  color: var(--paper-raised);
}

.close-foot p {
  margin: 0;
  font-size: 0.875rem;
  line-height: 1.4;
}

@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: minmax(0, 1fr);
  }

  .hero-copy,
  .hero-art {
    grid-column: 1;
  }

  .hero-art {
    justify-self: start;
    max-width: 460px;
    margin-top: clamp(28px, 5vw, 44px);
  }
}

@media (max-width: 800px) {
  .close-inner {
    grid-template-columns: minmax(0, 1fr);
  }

  .close-actions {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    gap: 18px 28px;
    padding-bottom: 0;
  }
}

@media (max-width: 760px) {
  .feature {
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
  }

  .steps {
    grid-template-columns: minmax(0, 1fr);
    gap: clamp(26px, 6vw, 36px);
  }

  .step p {
    max-width: 44ch;
  }

  .close-foot {
    flex-direction: column;
    align-items: flex-start;
    gap: 6px;
  }
}

@media (max-width: 720px) {
  .primary-nav {
    display: none;
  }

  .header-cta {
    margin-left: auto;
  }

  .header-inner {
    min-height: 68px;
    gap: 16px;
  }
}

@media (max-width: 600px) {
  .hero {
    padding-top: 40px;
  }

  .hero-art {
    padding: 8px 10px 44px 0;
  }

  .sheet {
    box-shadow: 10px 10px 0 var(--shadow);
  }

  .bank-card {
    bottom: 0;
    width: 60%;
    box-shadow: 5px 7px 0 var(--shadow-strong);
  }

  .close-actions .btn {
    width: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
--w: 64%
--w: 42%
--w: 55%
--w: 72%
--w: 54%
--w: 54%
--w: 48%
--w: 66%
--w: 38%
--w: 58%
